def tool(data, params):
    code = params['series']
    cutoff = params['cutoff_year']
    regions = data['regions']
    names = data['names']
    series = data[code]
    by_region = {}
    total_with = 0
    total_recent = 0
    total_countries = 0
    for unit in series:
        for c in series[unit]:
            pass
    units = list(series.keys())
    merged = {}
    for unit in units:
        for c in series[unit]:
            merged[c] = series[unit][c]
    for c in merged:
        if c not in regions:
            continue
        obs = merged[c]
        years = [int(y) for y in obs if obs[y] is not None]
        if len(years) == 0:
            continue
        r = regions[c]
        if r not in by_region:
            by_region[r] = {'with_data': 0, 'recent': 0}
        by_region[r]['with_data'] += 1
        total_with += 1
        if max(years) >= cutoff:
            by_region[r]['recent'] += 1
            total_recent += 1
    facts = {'countries_with_any_estimate': total_with, 'countries_with_estimate_at_or_after_cutoff': total_recent, 'cutoff_year': cutoff}
    if total_with > 0:
        facts['share_recent_percent'] = round(100.0 * total_recent / total_with, 1)
    parts = []
    for r in sorted(by_region):
        facts['recent_' + r] = by_region[r]['recent']
        facts['with_data_' + r] = by_region[r]['with_data']
        parts.append(r + ': ' + str(by_region[r]['recent']) + ' of ' + str(by_region[r]['with_data']))
    summary = 'Of ' + str(total_with) + ' countries with any value for ' + code + ', ' + str(total_recent) + ' have a value dated ' + str(cutoff) + ' or later. By region: ' + '; '.join(parts) + '. Countries without any value are not counted; whether a dated value is survey-based or modelled is not stated by the series itself.'
    return {'facts': facts, 'summary': summary}

def tool(data, params):
    code = params['series']
    start = int(params.get('start_year', 2015))
    end = int(params.get('end_year', 2022))
    s = data[code]
    regions = data['regions']
    names = data['names']
    counts = {}
    for y in range(start, end + 1):
        counts[y] = 0
    latest = {}
    for unit in s:
        if unit not in regions:
            continue
        obs = s[unit]
        for y in obs:
            yy = int(y)
            v = obs[y]
            if v is None or yy < start or yy > end:
                continue
            counts[yy] += 1
            if unit not in latest or yy > latest[unit]:
                latest[unit] = yy
    facts = {}
    for y in range(start, end + 1):
        facts['countries_' + str(y)] = counts[y]
    total = len(latest)
    facts['countries_with_any_estimate'] = total
    facts['countries_in_scope'] = len(regions)
    if total > 0:
        yrs = [latest[u] for u in latest]
        facts['median_latest_year'] = statistics.median(yrs)
        facts['oldest_latest_year'] = min(yrs)
        facts['newest_latest_year'] = max(yrs)
        peak = max(range(start, end + 1), key=lambda y: counts[y])
        facts['peak_year'] = peak
        facts['coverage_share_pct'] = round(100.0 * total / max(1, len(regions)), 1)
    else:
        facts['note'] = 'no observations in window'
    summary = 'Series ' + code + ': ' + str(total) + ' of ' + str(len(regions)) + ' countries have at least one observation between ' + str(start) + ' and ' + str(end) + '. Counts per year are given as facts; countries without an observation are missing, not zero.'
    return {'facts': facts, 'summary': summary}

