def tool(data, params):
    code = params['series']
    y0 = params.get('start_year', 2000)
    y1 = params.get('end_year', 2022)
    s = data[code]
    regions = data['regions']
    names = data['names']
    latest = {}
    for c, ys in s.items():
        pts = [(int(y), v) for y, v in ys.items() if v is not None and y0 <= int(y) <= y1]
        if pts:
            latest[c] = max(pts)
    vals = [p[1] for p in latest.values()]
    facts = {}
    facts['countries_with_data'] = len(vals)
    facts['countries_in_regions'] = len(regions)
    if not vals:
        return {'facts': facts, 'summary': 'No observations exist for series ' + code + ' between ' + str(y0) + ' and ' + str(y1) + '.'}
    facts['median'] = round(statistics.median(vals), 2)
    facts['mean'] = round(statistics.mean(vals), 2)
    top = max(latest, key=lambda c: latest[c][1])
    low = min(latest, key=lambda c: latest[c][1])
    facts['highest_country'] = names.get(top, top)
    facts['highest_value'] = round(latest[top][1], 2)
    facts['highest_year'] = latest[top][0]
    facts['lowest_country'] = names.get(low, low)
    facts['lowest_value'] = round(latest[low][1], 2)
    facts['lowest_year'] = latest[low][0]
    groups = {}
    for c, p in latest.items():
        r = regions.get(c)
        if r is not None:
            groups.setdefault(r, []).append(p[1])
