def tool(data, params):
    code = params['series']
    year_from = params.get('year_from', 2010)
    year_to = params.get('year_to', 2024)
    top_n = params.get('top_n', 5)
    s = data[code]
    regions = data['regions']
    names = data['names']
    latest = {}
    for unit in s:
        for c in s[unit]:
            if c not in regions:
                continue
            for y in s[unit][c] if isinstance(s[unit][c], dict) else []:
                pass
    best = {}
    for c in s:
        if c not in regions:
            continue
        ser = s[c]
        ys = [y for y in ser if year_from <= int(y) <= year_to and ser[y] is not None]
        if ys:
            y = max(ys, key=lambda k: int(k))
            best[c] = (int(y), ser[y])
    vals = [v for (y, v) in best.values()]
    facts = {'countries_with_data': len(vals), 'window': str(year_from) + '-' + str(year_to)}
    if not vals:
        return {'facts': facts, 'summary': 'No country has an observation in the window; the series is missing for ' + str(year_from) + '-' + str(year_to) + '.'}
    facts['median'] = round(statistics.median(vals), 2)
    facts['mean'] = round(statistics.mean(vals), 2)
    facts['min'] = round(min(vals), 2)
    facts['max'] = round(max(vals), 2)
    facts['below_25'] = len([v for v in vals if v < 25])
    rk = sorted(best, key=lambda c: best[c][1])
    low = rk[:top_n]
    high = rk[::-1][:top_n]
    facts['lowest'] = '; '.join(names.get(c, c) + ' ' + str(round(best[c][1], 1)) + ' (' + str(best[c][0]) + ')' for c in low)
    facts['highest'] = '; '.join(names.get(c, c) + ' ' + str(round(best[c][1], 1)) + ' (' + str(best[c][0]) + ')' for c in high)
    reg = {}
    for c in best:
        reg.setdefault(regions[c], []).append(best[c][1])
    for r in sorted(reg):
        facts['median_region_' + r] = round(statistics.median(reg[r]), 2)
    summary = 'Across ' + str(len(vals)) + ' countries, latest coverage of all social protection and labour programmes among the poorest quintile in ' + str(year_from) + '-' + str(year_to) + ' has a median of ' + str(facts['median']) + ' % of the quintile population, ranging from ' + str(facts['min']) + ' to ' + str(facts['max']) + '. Survey years differ between countries, so values are not strictly comparable.'
    return {'facts': facts, 'summary': summary}

